<script setup lang="ts">
import {t as tr} from "../i18n";
import {computed,nextTick,onMounted,ref,watch} from 'vue';import {useHistoryOverlay} from '../composables/useHistoryOverlay';import {useSessionStore,type RoundEffects,type Round} from '../stores/session';import {useRunStore} from '../stores/run';import type {useConversationController} from '../composables/useConversationController';import ChatMessage from '../components/ChatMessage.vue';import RoundToolbar from '../components/RoundToolbar.vue';import RoundActionDialog from '../components/RoundActionDialog.vue';import {useVisibleRefresh} from '../composables/useVisibleRefresh';import AsyncState from './AsyncState.vue';import {useFeedback} from './feedback';import UiIcon from '../components/UiIcon.vue';import {useVoiceInput} from '../composables/useVoiceInput';
import {useHoldToTalk} from '../composables/useHoldToTalk';
const props=defineProps<{conversationId:string;controller:ReturnType<typeof useConversationController>}>(),session=useSessionStore(),run=useRunStore(),feedback=useFeedback(),draft=ref(''),scroller=ref<HTMLElement>(),nearBottom=ref(true),newMessages=ref(false),error=ref(''),effects=ref<string[]>([]),roundBusy=ref(false),dialog=ref<{kind:'rollback'|'edit';id:string;question:string;index:number}|null>(null);
const voice=useVoiceInput(),voiceHint=computed(()=>{const code=voice.errorCode.value;if(!code||code==='aborted')return '';const messages:Partial<Record<string,string>>={unsupported:tr('当前浏览器不支持录音'),insecure:tr('语音输入需要 HTTPS 或 localhost 环境'),denied:tr('麦克风权限被拒绝，请在浏览器地址栏允许后重试'),no_device:tr('未检测到可用麦克风'),busy:tr('已有录音在进行'),network:tr('网络异常，转写失败'),not_configured:tr('语音识别未配置：请在服务端 .env 设置 ASR_API_KEY'),rate_limited:tr('语音转写已达每小时配额，请稍后再试'),upstream:tr('识别服务暂不可用，请稍后重试'),empty:tr('没有听清，请靠近一点再说一次'),unknown:tr('语音识别失败，请重试')};return messages[code]||'';});
const voiceMode=ref(false),textareaRef=ref<HTMLTextAreaElement|null>(null);
const hold=useHoldToTalk({voice,onText:(recognized)=>{draft.value=draft.value?draft.value.replace(/\s+$/,'')+' '+recognized:recognized;voiceMode.value=false;void nextTick(()=>textareaRef.value?.focus());}});
/** 点麦克风只切形态，不开始录音；录音靠长按语音条（微信口径：避免误触即上传） */
function enterVoice():void{if(busy.value||voice.working.value)return;voiceMode.value=true;}
/** 点键盘回文本模式：草稿原样保留并聚焦，不丢已识别内容 */
function exitVoice():void{voiceMode.value=false;void nextTick(()=>textareaRef.value?.focus());}
const mode=computed(()=>session.currentMode()),busy=computed(()=>run.inputLocked||props.controller.submitting.value||Boolean(session.activeRuns[props.conversationId]));
// A10：移动端模式开关——与会话页顶部的说明标签并排，点击即切（服务端已解锁，
// 模式随发送时刻生效、历史消息语义不变）；运行中/切换中禁用，失败走既有 error 行。
const switching=ref(false);
async function setMode(m:'chat'|'task'):Promise<void>{if(m===mode.value||switching.value||busy.value)return;switching.value=true;try{await session.changeConversationMode(props.conversationId,m);}catch(e){error.value=(e as Error).message;}finally{switching.value=false;}}
const dialogOpen=computed({get:()=>Boolean(dialog.value),set:value=>{if(!value)dialog.value=null;}});useHistoryOverlay(dialogOpen);
async function load(){if(props.controller.activeConversation.value!==props.conversationId)await session.openConversation(props.conversationId);else session.saveCurrentId(props.conversationId);draft.value=session.draftFor(props.conversationId);}
onMounted(load);watch(()=>props.conversationId,load);watch(draft,value=>session.saveDraft(props.conversationId,value));
useVisibleRefresh(()=>session.syncConversation(props.conversationId),()=>props.controller.activeConversation.value!==props.conversationId);
function onScroll(){const e=scroller.value;if(e){nearBottom.value=e.scrollHeight-e.scrollTop-e.clientHeight<100;if(nearBottom.value)newMessages.value=false;}}
async function latest(){nearBottom.value=true;newMessages.value=false;await nextTick();if(scroller.value)scroller.value.scrollTop=scroller.value.scrollHeight;}
watch(()=>session.currentMessages.map(m=>m.text+m.status).join('|'),async()=>{if(nearBottom.value)await latest();else newMessages.value=true;});
async function send(){const text=draft.value;if(!text.trim()||busy.value)return;nearBottom.value=true;void props.controller.submit(text,mode.value);}
function key(e:KeyboardEvent){if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();void send();}}
function describe(result:RoundEffects|undefined){if(!result)return [];return [...result.notes,...result.reverted.map(r=>'已回退沙盒对象 '+r.objectId),...result.rejectedPlans.map(id=>'已作废待确认方案 '+id),...result.supersededProposals.map(id=>'已作废待确认提案 '+id),...result.cancelledTasks.map(id=>'已取消任务 '+id),...result.notReverted.map(r=>'未回退 '+r.objectId+'：'+r.reason),...result.blocked.map(r=>'原系统已提交，需人工处理：'+r.planId+' '+r.objects.map(o=>o.id).join('、'))];}
async function remove(round:Round){if(busy.value||!round.userMessage)return;const ok=await feedback.confirmSheet({title:tr('删除本轮提问与回答？'),message:tr('作废未确认方案；已提交业务不会撤销。'),confirmLabel:tr('删除'),cancelLabel:tr('取消'),destructive:true});if(!ok)return;roundBusy.value=true;const result=await session.deleteRound(props.conversationId,round.userMessage.id);roundBusy.value=false;if(result.ok){effects.value=describe(result.effects);feedback.toast(tr('已删除本轮'));}else error.value=result.message||'删除未成功';}
function openRound(kind:'rollback'|'edit',round:Round,index:number){if(!round.userMessage||busy.value||mode.value!=='task')return;dialog.value={kind,id:round.userMessage.id,question:round.userMessage.text,index:index+1};error.value='';}
async function confirmRound(input:{text:string;revertEffects:boolean}){if(!dialog.value||roundBusy.value)return;roundBusy.value=true;const selected={...dialog.value},result=await session.rollbackRound(props.conversationId,selected.id,input.revertEffects);roundBusy.value=false;if(!result.ok){error.value=result.message||'回档失败，已保留修改内容';return;}effects.value=describe(result.effects);dialog.value=null;if(selected.kind==='edit'){draft.value=input.text;await props.controller.submit(input.text,'task');}}
watch(()=>run.runStatus,value=>{if(value!=='running')draft.value=session.draftFor(props.conversationId);});
</script>
<template><div class="mobile-conversation"><div class="mobile-conversation-heading"><span class="m-mode-tag">{{tr(mode==='chat'?'查询与对话（不办理业务）':'可办理的工作对话')}}</span><div class="m-mode-switch" role="group" :aria-label="tr('会话模式')"><button type="button" class="m-mode-switch__opt" :class="{'is-active':mode==='task'}" :disabled="switching||busy" :aria-pressed="mode==='task'" @click="setMode('task')">{{tr('工作')}}</button><button type="button" class="m-mode-switch__opt" :class="{'is-active':mode==='chat'}" :disabled="switching||busy" :aria-pressed="mode==='chat'" @click="setMode('chat')">{{tr('聊天')}}</button></div></div><div ref="scroller" class="mobile-messages" @scroll.passive="onScroll"><p v-for="(line,i) in effects" :key="i" class="mobile-warning">{{line}}</p><p v-if="error||controller.error.value" role="alert">{{error||controller.error.value}}</p><AsyncState :loading="session.messagesLoading" :error="session.currentMessagesError||''" @retry="session.syncConversation(conversationId)"><p v-if="!session.currentMessages.length" class="mobile-state">{{tr(mode==='chat'?'查询课表、房间状态或钥匙登记。':'查询实验室，或准备报修、交接和调课。')}}</p><article v-for="(round,index) in session.currentRounds" :key="round.key" class="mobile-round"><ChatMessage v-for="message in round.messages" :key="message.id" :msg="message" @retry="draft=round.userMessage?.text||''"/><RoundToolbar :index="index+1" :can-rewind="mode==='task'" :busy="busy||roundBusy" :actionable="Boolean(round.userMessage)" @remove="remove(round)" @rollback="openRound('rollback',round,index)" @edit="openRound('edit',round,index)"/></article></AsyncState></div><button v-if="newMessages" class="mobile-new-messages" @click="latest">{{tr("有新消息 · 查看")}}</button><form class="mobile-composer" @submit.prevent="send"><div v-if="voice.working.value" class="mobile-voice-bar" role="status"><span class="mobile-voice-dot" aria-hidden="true"></span><b>{{tr(voice.status.value==='transcribing'?'识别中…':voice.status.value==='requesting'?'等待麦克风…':'正在聆听')}}</b><span class="mobile-voice-time">{{Math.floor(voice.seconds.value)}}s / 60s</span><button type="button" @click="hold.cancel">{{tr("取消")}}</button></div><label class="sr-only" for="mobile-question">{{tr("输入问题")}}</label><button v-if="voice.supported.value&&!voiceMode" type="button" class="mobile-mic" :disabled="busy||Boolean(session.currentMessagesError)" :aria-label="tr('语音输入')" @click="enterVoice"><UiIcon name="mic"/></button><button v-else-if="voice.supported.value&&voiceMode" type="button" class="mobile-mic" :disabled="busy" :aria-label="tr('切换到键盘')" @click="exitVoice"><UiIcon name="keyboard"/></button><button v-if="voiceMode" type="button" class="mobile-speak" :class="{'is-recording':voice.status.value==='recording','is-sliding':hold.sliding.value}" :disabled="busy||Boolean(session.currentMessagesError)" v-on="hold.handlers"><span>{{tr(hold.sliding.value?'松开取消':voice.status.value==='recording'?'松开结束':'按住 说话')}}</span></button><textarea v-else ref="textareaRef" id="mobile-question" v-model="draft" rows="2" maxlength="3000" :disabled="busy||voice.working.value||Boolean(session.currentMessagesError)" :placeholder="mode==='chat'?'输入查询问题…':'输入要查询或办理的事项…'" @keydown="key"/><button v-if="busy" type="button" @click="controller.stop">{{tr("停止")}}</button><button v-else-if="!voiceMode" class="mobile-primary" :disabled="!draft.trim()||voice.working.value||Boolean(session.currentMessagesError)" type="submit">{{tr("发送")}}</button><p v-if="voiceHint" class="mobile-voice-hint" role="alert">{{voiceHint}}</p><small v-if="session.activeRuns[conversationId]&&!run.inputLocked">{{tr("服务端仍在生成，保留运行编号")}} {{session.activeRuns[conversationId]}}{{tr("；刷新回查。")}}</small></form><RoundActionDialog :open="Boolean(dialog)" :kind="dialog?.kind||'rollback'" :round-index="dialog?.index||1" :question="dialog?.question||''" :busy="roundBusy" :error="error" :has-business-writes="true" @cancel="dialog=null" @confirm="confirmRound"/></div></template>
<style scoped>
/* A10：会话模式开关——与说明标签同行右对齐，紧凑分段（左=工作/右=聊天） */
.mobile-conversation-heading{display:flex;align-items:center;justify-content:space-between;gap:8px}
.m-mode-switch{display:flex;gap:2px;padding:2px;background:var(--m-tonal,var(--surface-3));border:1px solid var(--m-hairline,var(--border));border-radius:999px;flex-shrink:0}
.m-mode-switch__opt{border:0;background:transparent;border-radius:999px;padding:4px 12px;font:600 calc(var(--ui-font-size) * 0.84615) var(--font-sans);color:var(--text-muted);cursor:pointer;white-space:nowrap}
.m-mode-switch__opt.is-active{background:var(--primary);color:var(--primary-contrast,#fff)}
.m-mode-switch__opt:disabled{cursor:wait;opacity:.6}
</style>
